ALTER TABLE public.questions ADD COLUMN image_path text;
CREATE POLICY "Authenticated users read question images" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'question-images');
CREATE POLICY "Admins upload question images" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'question-images' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins remove question images" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'question-images' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins update question images" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'question-images' AND public.has_role(auth.uid(), 'admin')) WITH CHECK (bucket_id = 'question-images' AND public.has_role(auth.uid(), 'admin'));